/* Afterword landing. Slate neutrals, one terracotta accent, light + dark. */

:root {
  --bg: #f4f5f6;
  --surface: #fcfcfd;
  --surface-2: #e9ecef;
  --ink: #16191d;
  --ink-2: #4a525c;
  --line: #d7dce1;
  --accent: #b5400f;
  --accent-ink: #fdf8f5;
  --accent-soft: #f6e3d9;
  --mark: #fbd9c6;
  --shadow: 0 1px 2px rgb(22 25 29 / .06), 0 12px 32px -12px rgb(22 25 29 / .18);
  --radius: 14px;
  --radius-sm: 8px;
  --ease: cubic-bezier(.16, 1, .3, 1);
  --font: "Geist", ui-sans-serif, system-ui, sans-serif;
  --mono: "Geist Mono", ui-monospace, monospace;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #111418;
    --surface: #181c21;
    --surface-2: #20262d;
    --ink: #eef0f2;
    --ink-2: #a6afb9;
    --line: #2c333b;
    --accent: #f08a5d;
    --accent-ink: #1a0f0a;
    --accent-soft: #3a2219;
    --mark: #5a2f1c;
    --shadow: 0 1px 2px rgb(0 0 0 / .3), 0 16px 40px -16px rgb(0 0 0 / .6);
  }
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 1.0625rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { display: block; max-width: 100%; height: auto; }
a { color: inherit; }
h1, h2, h3 { margin: 0; line-height: 1.15; letter-spacing: -0.02em; text-wrap: balance; }
p { margin: 0; }
ul { margin: 0; padding: 0; list-style: none; }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 4px; }

.wrap { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1.25rem; }
@media (min-width: 768px) { .wrap { padding: 0 2rem; } }

.skip {
  position: absolute; left: 1rem; top: -3rem; z-index: 20;
  background: var(--ink); color: var(--bg); padding: .5rem .875rem; border-radius: var(--radius-sm);
}
.skip:focus { top: 1rem; }

/* Buttons: pill for interactive, 14px for cards, 8px for small chips. */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 48px; padding: 0 1.375rem;
  border-radius: 999px; border: 1px solid transparent;
  font: 600 1rem/1 var(--font); text-decoration: none; white-space: nowrap; cursor: pointer;
  transition: transform .2s var(--ease), background-color .2s var(--ease), border-color .2s var(--ease);
}
.btn:active { transform: translateY(1px) scale(.98); }
.btn--primary { background: var(--accent); color: var(--accent-ink); }
.btn--primary:hover { background: color-mix(in srgb, var(--accent) 88%, var(--ink)); }
.btn--ghost { border-color: var(--line); color: var(--ink); background: var(--surface); }
.btn--ghost:hover { border-color: var(--ink-2); }
.btn--sm { min-height: 44px; padding: 0 1.125rem; font-size: .9375rem; }
.btn--block { width: 100%; }

/* Nav */
.nav {
  position: sticky; top: 0; z-index: 10;
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}
.nav__inner { display: flex; align-items: center; gap: 2rem; height: 68px; }
.brand { display: inline-flex; align-items: center; gap: .55rem; font-weight: 700; font-size: 1.125rem; text-decoration: none; letter-spacing: -0.01em; }
.brand__mark {
  display: grid; place-items: center; width: 28px; height: 28px; border-radius: var(--radius-sm);
  background: var(--ink); color: var(--bg); font-size: .9375rem;
}
.nav__links { display: none; gap: 1.75rem; }
.nav__links a, .link-quiet { text-decoration: none; color: var(--ink-2); font-weight: 500; font-size: .9375rem; padding: .625rem 0; }
.nav__links a:hover, .link-quiet:hover { color: var(--ink); }
.nav__actions { margin-left: auto; display: flex; align-items: center; gap: 1.25rem; }
.link-quiet { display: none; }
@media (min-width: 768px) {
  .nav__links { display: flex; }
  .link-quiet { display: inline; }
}

/* Hero */
.hero { padding: 3rem 0 4.5rem; }
.hero__grid { display: grid; gap: 3rem; align-items: center; }
.hero__title { font-size: clamp(2.5rem, 5.4vw, 4rem); font-weight: 700; letter-spacing: -0.035em; line-height: 1.05; max-width: 14ch; }
.hero__sub { margin-top: 1.25rem; font-size: 1.1875rem; color: var(--ink-2); max-width: 40ch; }
.hero__ctas { margin-top: 2rem; display: flex; flex-wrap: wrap; gap: .75rem; }

.hero__visual { position: relative; padding-bottom: 4rem; }
.hero__photo { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border-radius: var(--radius); background: var(--surface-2); }

.tasks {
  position: absolute; left: 1rem; right: 1rem; bottom: 0;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 1.125rem 1.25rem; box-shadow: var(--shadow);
}
.tasks__title { display: flex; justify-content: space-between; align-items: baseline; font-weight: 600; font-size: .9375rem; margin-bottom: .5rem; }
.tasks__count { font: 500 .8125rem var(--mono); color: var(--ink-2); }
.task { display: flex; gap: .75rem; align-items: flex-start; padding: .5rem 0; cursor: pointer; }
.task input {
  appearance: none; -webkit-appearance: none; flex: none;
  width: 20px; height: 20px; margin: .2rem 0 0; border: 1.5px solid var(--ink-2); border-radius: 6px;
  display: grid; place-items: center; cursor: pointer; transition: background-color .2s var(--ease), border-color .2s var(--ease);
}
.task input::after {
  content: ""; width: 10px; height: 6px; margin-top: -2px;
  border-left: 2px solid var(--accent-ink); border-bottom: 2px solid var(--accent-ink);
  transform: rotate(-45deg) scale(0); transition: transform .2s var(--ease);
}
.task input:checked { background: var(--accent); border-color: var(--accent); }
.task input:checked::after { transform: rotate(-45deg) scale(1); }
.task__body { display: flex; flex-direction: column; gap: .1rem; }
.task__text { font-size: .9375rem; line-height: 1.4; transition: color .2s var(--ease); }
.task input:checked + .task__body .task__text { color: var(--ink-2); text-decoration: line-through; }
.task__meta { font: 400 .8125rem var(--mono); color: var(--ink-2); }

@media (min-width: 960px) {
  .hero { padding: 4.5rem 0 6rem; }
  .hero__grid { grid-template-columns: 1.05fr 1fr; gap: 4rem; }
  .tasks { left: -3rem; right: auto; width: min(360px, 90%); }
}

/* Section titles */
.section-title { font-size: clamp(1.875rem, 3.4vw, 2.75rem); font-weight: 700; letter-spacing: -0.03em; max-width: 20ch; }

/* Features bento: lead cell spans two rows, two cells on the right. */
.features { padding: 5rem 0; border-top: 1px solid var(--line); }
.bento { margin-top: 2.5rem; display: grid; gap: 1rem; }
.bento__cell {
  border-radius: var(--radius); padding: 1.75rem; background: var(--surface); border: 1px solid var(--line);
  display: flex; flex-direction: column; gap: .75rem;
}
.bento__cell h3 { font-size: 1.375rem; max-width: 24ch; }
.bento__cell p { color: var(--ink-2); max-width: 46ch; }
.bento__cell--tint { background: var(--accent-soft); border-color: transparent; }
.bento__cell--photo { padding: 0; overflow: hidden; }
.bento__cell--photo img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; background: var(--surface-2); }
.bento__photo-copy { padding: 1.5rem 1.75rem 1.75rem; display: flex; flex-direction: column; gap: .5rem; }

.transcript { margin: 1rem 0 0; padding: 1.25rem; background: var(--bg); border-radius: var(--radius-sm); border: 1px solid var(--line); }
.transcript blockquote { margin: 0; }
.transcript blockquote p { color: var(--ink); font-size: 1rem; max-width: none; }
.speaker { display: block; font: 500 .8125rem var(--mono); color: var(--ink-2); margin-bottom: .25rem; }
.transcript mark { background: var(--mark); color: inherit; padding: .05em .2em; border-radius: 4px; }
.transcript__result {
  margin-top: 1rem; padding-top: 1rem; border-top: 1px dashed var(--line);
  display: flex; flex-wrap: wrap; align-items: baseline; gap: .5rem; font-weight: 600; font-size: .9375rem;
}
.transcript__arrow { color: var(--accent); }
.transcript__result .task__meta { font-weight: 400; margin-left: auto; }

.logos { margin-top: auto; padding-top: 1rem; display: flex; flex-wrap: wrap; gap: .625rem; }
.logos li { display: grid; place-items: center; width: 52px; height: 52px; border-radius: var(--radius-sm); background: var(--surface); }

@media (min-width: 768px) {
  .bento { grid-template-columns: 1.25fr 1fr; grid-template-rows: auto auto; }
  .bento__cell--lead { grid-row: span 2; padding: 2.25rem; }
  .bento__cell--lead h3 { font-size: 1.75rem; }
}

/* Testimonials: one large, one compact, offset. */
.quotes { padding: 5rem 0; background: var(--surface); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.quotes__grid { margin-top: 2.5rem; display: grid; gap: 2.5rem; }
.quote { margin: 0; display: flex; flex-direction: column; gap: 1.5rem; }
.quote blockquote { margin: 0; }
.quote p { font-size: 1.25rem; line-height: 1.5; letter-spacing: -0.01em; max-width: 34ch; }
.quote--large p { font-size: clamp(1.5rem, 2.6vw, 2rem); line-height: 1.3; letter-spacing: -0.02em; max-width: 26ch; }
.quote figcaption { display: flex; align-items: center; gap: .875rem; }
.quote figcaption img { width: 48px; height: 48px; border-radius: 999px; object-fit: cover; background: var(--surface-2); }
.quote figcaption span { display: flex; flex-direction: column; font-size: .9375rem; color: var(--ink-2); line-height: 1.4; }
.quote figcaption strong { color: var(--ink); font-weight: 600; }

@media (min-width: 900px) {
  .quotes__grid { grid-template-columns: 1.5fr 1fr; gap: 4rem; align-items: end; }
  .quote:not(.quote--large) { padding-left: 2rem; border-left: 1px solid var(--line); margin-bottom: .5rem; }
}

/* Pricing */
.pricing { padding: 5rem 0 6rem; }
.pricing__grid { display: grid; gap: 2.5rem; }
.pricing__intro p { margin-top: 1rem; color: var(--ink-2); max-width: 36ch; }

.billing { margin-top: 1.75rem; display: inline-flex; padding: 4px; gap: 4px; background: var(--surface-2); border-radius: 999px; }
.billing__opt {
  min-height: 40px; padding: 0 1rem; border: 0; border-radius: 999px; background: transparent;
  color: var(--ink-2); font: 500 .9375rem var(--font); cursor: pointer; white-space: nowrap;
  transition: background-color .2s var(--ease), color .2s var(--ease);
}
.billing__opt[aria-pressed="true"] { background: var(--surface); color: var(--ink); box-shadow: 0 1px 2px rgb(22 25 29 / .12); }
.billing__save { font-size: .8125rem; color: var(--accent); margin-left: .25rem; }

.plans { display: grid; gap: 1rem; }
.plan {
  padding: 2rem; border-radius: var(--radius); background: var(--surface); border: 1px solid var(--line);
  display: flex; flex-direction: column;
}
.plan--featured { border-color: var(--accent); box-shadow: var(--shadow); }
.plan__name { font-size: 1.25rem; }
.plan__desc { margin-top: .375rem; color: var(--ink-2); font-size: .9375rem; }
.plan__price { margin: 1.5rem 0; display: flex; align-items: baseline; gap: .5rem; }
.plan__amount { font-size: 3rem; font-weight: 700; letter-spacing: -0.04em; line-height: 1; font-variant-numeric: tabular-nums; }
.plan__unit { color: var(--ink-2); font-size: .9375rem; }
.plan__list { display: grid; gap: .75rem; margin-bottom: 2rem; flex: 1; }
.plan__list li { position: relative; padding-left: 1.5rem; font-size: .9375rem; }
.plan__list li::before {
  content: ""; position: absolute; left: 2px; top: .45em; width: 9px; height: 5px;
  border-left: 2px solid var(--accent); border-bottom: 2px solid var(--accent); transform: rotate(-45deg);
}

@media (min-width: 768px) { .plans { grid-template-columns: 1fr 1fr; } }
@media (min-width: 1024px) { .pricing__grid { grid-template-columns: 1fr 2fr; gap: 4rem; align-items: start; } }

/* Footer */
.footer { border-top: 1px solid var(--line); padding: 2rem 0; }
.footer__inner { display: flex; flex-wrap: wrap; align-items: center; gap: 1rem 2rem; }
.footer__links { display: flex; gap: 1.5rem; }
.footer__links a { color: var(--ink-2); text-decoration: none; font-size: .9375rem; }
.footer__links a:hover { color: var(--ink); }
.footer__copy { margin-left: auto; color: var(--ink-2); font-size: .875rem; }

/* Motion: page-load stagger on the hero, scroll reveal elsewhere. Only when motion is allowed. */
@media (prefers-reduced-motion: no-preference) {
  .load { animation: rise .8s var(--ease) both; animation-delay: calc(var(--i) * 90ms); }
  .js .reveal { opacity: 0; transform: translateY(18px); transition: opacity .7s var(--ease), transform .7s var(--ease); }
  .js .reveal.is-in { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition-duration: .01ms !important; animation: none !important; }
}
@keyframes rise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }

