1	document.addEventListener("DOMContentLoaded", () => {
2	  // Hero action items: keep the open count in sync with the checkboxes.
3	  const count = document.getElementById("task-count");
4	  const boxes = document.querySelectorAll(".tasks input[type=checkbox]");
5	  const updateCount = () => {
6	    const open = [...boxes].filter((b) => !b.checked).length;
7	    count.textContent = open === 0 ? "All done" : `${open} open`;
8	  };
9	  boxes.forEach((b) => b.addEventListener("change", updateCount));
10	
11	  // Billing toggle: swap plan prices between monthly and annual.
12	  const options = document.querySelectorAll(".billing__opt");
13	  const amounts = document.querySelectorAll(".plan__amount");
14	  options.forEach((opt) => {
15	    opt.addEventListener("click", () => {
16	      const period = opt.dataset.period;
17	      options.forEach((o) => o.setAttribute("aria-pressed", String(o === opt)));
18	      amounts.forEach((a) => { a.textContent = `$${a.dataset[period]}`; });
19	    });
20	  });
21	});
